import React from "react";

class Movie extends React.Component {
  constructor(props){
    super(props)
    this.state = {
      moviesArray: this.props.movieArray
    }
  }
  render() {
    return <div>
        <h1>Movies: </h1>
        <div>
          
        </div>
        <h1>Title: {this.state.moviesArray[0].title}</h1>
        <h1>Genre: {this.state.moviesArray[0].genre}</h1>
        <h1>Rating: {this.state.moviesArray[0].rated}</h1>
        <h1>Release Date: {this.state.moviesArray[0].releaseDate}</h1>
        {console.log(this.state.moviesArray)}
        
      </div>
  }
}
export default Movie;
